def encode_shift(s: str):
    """
    Returns an encoded string by shifting every character by 5 in the alphabet.
    Only lowercase letters 'a'-'z' are shifted; other characters remain unchanged.
    """
    base = ord("a")
    return "".join(
        chr((ord(ch) - base + 5) % 26 + base) if "a" <= ch <= "z" else ch
        for ch in s
    )


def decode_shift(s: str):
    """
    Decodes a string that was encoded with encode_shift.
    Only lowercase letters 'a'-'z' are decoded; other characters remain unchanged.
    """
    base = ord("a")
    return "".join(
        chr((ord(ch) - base - 5) % 26 + base) if "a" <= ch <= "z" else ch
        for ch in s
    )

